package org.cloudburstmc.protocol.bedrock.codec.v924.serializer;
import io.netty.buffer.ByteBuf; import org.cloudburstmc.math.vector.Vector3f; import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper; import org.cloudburstmc.protocol.bedrock.codec.v859.serializer.DebugDrawerSerializer_v859; import org.cloudburstmc.protocol.bedrock.data.debugshape.*; import org.cloudburstmc.protocol.common.util.VarInts; import java.awt.Color;
public class DebugDrawerSerializer_v924 extends DebugDrawerSerializer_v859 { public static final DebugDrawerSerializer_v924 INSTANCE=new DebugDrawerSerializer_v924();
@Override protected void writeCommonShapeData(ByteBuf b,BedrockCodecHelper h,DebugShape s){VarInts.writeUnsignedLong(b,s.getId());h.writeOptionalNull(b,s.getType(),(x,t)->x.writeByte(t.ordinal()));h.writeOptionalNull(b,s.getPosition(),WRITE_VECTOR3F);h.writeOptionalNull(b,s.getScale(),ByteBuf::writeFloatLE);h.writeOptionalNull(b,s.getRotation(),WRITE_VECTOR3F);h.writeOptionalNull(b,s.getTotalTimeLeft(),ByteBuf::writeFloatLE);h.writeOptionalNull(b,s.getColor(),WRITE_COLOR);h.writeOptionalNull(b,s.getDimension(),VarInts::writeInt);h.writeOptionalNull(b,s.getAttachedToEntityId(),VarInts::writeUnsignedLong);}
@Override protected DebugShape readShape(ByteBuf b,BedrockCodecHelper h){long id=VarInts.readUnsignedLong(b);DebugShape.Type t=h.readOptional(b,null,(x,a)->SHAPE_TYPES[x.readUnsignedByte()]);Vector3f pos=h.readOptional(b,null,READ_VECTOR3F);Float sc=h.readOptional(b,null,ByteBuf::readFloatLE);Vector3f rot=h.readOptional(b,null,READ_VECTOR3F);Float ttl=h.readOptional(b,null,ByteBuf::readFloatLE);Color col=h.readOptional(b,null,READ_COLOR);Integer dim=h.readOptional(b,-1,VarInts::readInt);Long ent=h.readOptional(b,null,VarInts::readUnsignedLong);VarInts.readUnsignedInt(b);if(t==null)return new DebugShape(id,dim);switch(t){case ARROW:Vector3f ep=h.readOptional(b,null,READ_VECTOR3F);Float hl=h.readOptional(b,null,ByteBuf::readFloatLE);Float hr=h.readOptional(b,null,ByteBuf::readFloatLE);Integer hs=h.readOptional(b,null,x->x.readUnsignedByte());return new DebugArrow(id,dim,pos,sc,rot,ttl,col,ep,hl,hr,hs,ent);case BOX:Vector3f bb=h.readVector3f(b);return new DebugBox(id,dim,pos,sc,rot,ttl,col,bb,ent);case CIRCLE:return new DebugCircle(id,dim,pos,sc,rot,ttl,col,(int)b.readUnsignedByte(),ent);case LINE:return new DebugLine(id,dim,pos,sc,rot,ttl,col,h.readVector3f(b),ent);case SPHERE:return new DebugSphere(id,dim,pos,sc,rot,ttl,col,(int)b.readUnsignedByte(),ent);case TEXT:return new DebugText(id,dim,pos,sc,rot,ttl,col,h.readString(b),ent);default:throw new IllegalStateException("Unknown debug shape type");}}}
